import json,html
from pathlib import Path
from pipeline import report,ROOT
payload=json.dumps(report()).replace('</','<\\/')
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VAULT360 | Finance & Risk Data Architecture</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--bg:#090f1b;--panel:#111c2d;--stroke:#26364b;--ink:#eef5ff;--muted:#8fa2bb;--mint:#65ebc5;--gold:#f9c66c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% -10%,#1b3d51 0,transparent 45%),var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif}header{padding:25px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--stroke)}.logo{font:700 25px 'Space Grotesk';letter-spacing:-1px}.logo span{color:var(--mint)}.tag{color:var(--mint);border:1px solid #2b655b;border-radius:50px;padding:8px 13px;font-size:12px}main{max-width:1320px;margin:auto;padding:35px 25px 90px}.eyebrow{color:var(--mint);letter-spacing:2px;font-size:12px;font-weight:700;text-transform:uppercase}h1{font:600 clamp(34px,5vw,64px)/1.08 'Space Grotesk';max-width:900px;margin:15px 0}h1 em{font-style:normal;color:var(--mint)}.intro{max-width:780px;color:var(--muted);line-height:1.7}nav{display:flex;flex-wrap:wrap;gap:9px;margin:34px 0 22px}button{border:1px solid var(--stroke);background:#17263a;color:#d9e7f8;border-radius:12px;padding:12px 17px;cursor:pointer;font:600 13px 'DM Sans'}button.active,button:hover{background:var(--mint);color:#0b1a24;border-color:var(--mint)}section{display:none}section.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.card{background:linear-gradient(150deg,#16243a,#0e1929);border:1px solid var(--stroke);border-radius:19px;padding:24px}.metric{font:600 37px 'Space Grotesk';margin:10px 0;color:var(--mint)}.small{color:var(--muted);font-size:13px;line-height:1.6}.panel{background:#111c2d;border:1px solid var(--stroke);border-radius:19px;padding:26px;margin-top:17px}.panel h2{font:600 22px 'Space Grotesk';margin:0 0 17px}.flow{display:flex;gap:10px;align-items:stretch;flex-wrap:wrap}.node{background:#192a3f;border:1px solid #36506a;border-radius:12px;padding:18px;min-width:140px;flex:1}.node b{display:block;color:var(--mint);margin-bottom:6px}.arrow{align-self:center;color:var(--gold);font-size:23px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--stroke);padding:14px 12px}th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:1px}.chart{display:flex;gap:12px;align-items:end;height:230px;padding:15px 0 0;border-bottom:1px solid #405269}.barwrap{flex:1;min-width:40px;text-align:center}.bar{background:linear-gradient(0deg,#1d9e94,#65ebc5);border-radius:8px 8px 0 0;min-height:3px}.barlabel{font-size:11px;color:var(--muted);margin-top:9px}.badge{display:inline-block;background:#23443d;color:#8ff6d4;padding:6px 10px;border-radius:8px;font-size:12px}.warn{background:#483a27;color:#ffd392}.cols{display:grid;grid-template-columns:1fr 1fr;gap:16px}.diagram{font:12px/1.7 monospace;white-space:pre-wrap;background:#08111f;padding:20px;border-radius:12px;color:#b9e4e1;overflow:auto}.note{margin-top:25px;color:var(--muted);font-size:12px}.download{margin:16px 0}.select{background:#17263a;color:white;border:1px solid var(--stroke);padding:10px;border-radius:9px}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr}header{padding:20px}main{padding:24px 15px}.tag{display:none}}
</style></head><body><header><div class="logo">VAULT<span>360</span> <small style="font-size:11px;color:#8fa2bb;font-weight:400">/ FINANCE & RISK</small></div><span class="tag">● LOCAL RESEARCH PROTOTYPE</span></header><main><div class="eyebrow">Enterprise Data Architecture / Demonstration</div><h1>From fragmented sources to <em>audit-ready thinking.</em></h1><p class="intro">An interactive look inside a Finance & Risk warehouse: Data Vault 2.0 inspired modeling, traceable ingestion, historized attributes, source-level quality controls and a reporting mart. Powered by an executable Python and SQL pipeline using fictional banking records.</p><nav><button class="active" data-tab="overview">01 / Mission control</button><button data-tab="architecture">02 / Vault anatomy</button><button data-tab="quality">03 / Quality & lineage</button><button data-tab="analytics">04 / Finance & Risk mart</button><button data-tab="governance">05 / Governance</button></nav><section id="overview" class="active"><div class="grid"><div class="card"><div class="small">Accepted transactions</div><div class="metric" id="transactions">—</div><div class="small">Hashed business keys</div></div><div class="card"><div class="small">Satellite history versions</div><div class="metric" id="versions">—</div><div class="small">Attribute traceability</div></div><div class="card"><div class="small">Quarantined source rows</div><div class="metric" id="quarantined">—</div><div class="small">Explicit validation failures</div></div><div class="card"><div class="small">Recorded ingestion batches</div><div class="metric" id="batches">—</div><div class="small">Fingerprint & load audit</div></div></div><div class="panel"><h2>The journey of a transaction</h2><div class="flow"><div class="node"><b>01 / SOURCE</b><small>Fictional banking CSV</small></div><div class="arrow">→</div><div class="node"><b>02 / VALIDATE</b><small>Schema, dates, amounts</small></div><div class="arrow">→</div><div class="node"><b>03 / RAW VAULT</b><small>Hubs, links, satellites</small></div><div class="arrow">→</div><div class="node"><b>04 / MART</b><small>Latest version, monthly facts</small></div></div></div><div class="panel"><h2>Why this matters</h2><p class="small">Finance and Risk teams need a shared understanding of business keys, source provenance, historical changes, reconciliations and repeatable definitions. This prototype makes the architecture inspectable, with the actual implementation available in the Python and SQL source files.</p><span class="badge">Executed locally with SQLite</span> <span class="badge warn">Not a production banking system</span></div></section><section id="architecture"><div class="cols"><div class="panel"><h2>Raw Vault model</h2><div class="diagram">HUB_CUSTOMER      HUB_ACCOUNT       HUB_TRANSACTION
     │                  │                   │
     └──── LINK_ACCOUNT_CUSTOMER ──────────┘
                        │
             LINK_TRANSACTION_ACCOUNT
                        │
               SAT_TRANSACTION_DETAIL
          amount / currency / booked_at
          hashdiff / load_dts / source</div></div><div class="panel"><h2>Modeling principles</h2><p class="small"><b style="color:#65ebc5">Hubs</b> store unique business identities using deterministic hashed keys.</p><p class="small"><b style="color:#65ebc5">Links</b> capture relationships between identities.</p><p class="small"><b style="color:#65ebc5">Satellites</b> preserve descriptive changes with load timestamps and source attribution.</p><p class="small">A latest-version query creates a simple analytical mart without overwriting the Raw Vault history.</p></div></div><div class="panel"><h2>SQL implementation detail</h2><div class="diagram">WITH latest AS (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY transaction_hk
    ORDER BY load_dts DESC
  ) AS rn
  FROM sat_transaction_detail
)
SELECT substr(booked_at,1,7) AS month,
       COUNT(*) AS transactions,
       SUM(amount) AS net_amount
FROM latest WHERE rn = 1
GROUP BY month ORDER BY month;</div></div></section><section id="quality"><div class="cols"><div class="panel"><h2>Quality gate</h2><p class="small">Source rows are checked for required fields, valid dates, numeric bounds and supported currency. Invalid records are quarantined with reason and original payload.</p><div class="metric" id="qualityPct">—</div><div class="small">Accepted source rows in the recorded batch</div></div><div class="panel"><h2>Lineage register</h2><div id="lineage"></div></div></div><div class="panel"><h2>Control design</h2><div class="flow"><div class="node"><b>File SHA256</b><small>Input fingerprint</small></div><div class="node"><b>Batch idempotency</b><small>Skip already loaded file</small></div><div class="node"><b>Row quarantine</b><small>Reject with reason</small></div><div class="node"><b>Record source</b><small>Attribute provenance</small></div></div></div></section><section id="analytics"><div class="panel"><h2>Monthly transaction activity</h2><p class="small">Bars represent number of accepted transactions, not money. All figures are synthetic.</p><div class="chart" id="chart"></div></div><div class="panel"><h2>Finance & Risk reporting mart</h2><div style="overflow:auto"><table><thead><tr><th>Month</th><th>Transactions</th><th>Net amount (SEK)</th></tr></thead><tbody id="mart"></tbody></table></div><div class="download"><button onclick="exportCsv()">↓ Export monthly mart CSV</button></div></div></section><section id="governance"><div class="cols"><div class="panel"><h2>Control register</h2><p class="small">✓ Traceable source names and ingestion timestamps</p><p class="small">✓ Rejected rows retained in quarantine</p><p class="small">✓ Hashdiff-driven satellite change capture</p><p class="small">✓ Deterministic business-key hashing</p><p class="small">✓ Documented lineage and transformation logic</p></div><div class="panel"><h2>Production readiness gaps</h2><p class="small">○ Cloud deployment and orchestration</p><p class="small">○ Enterprise access control and encryption</p><p class="small">○ Effective dating and concurrent loads</p><p class="small">○ Automated reconciliation with finance ledgers</p><p class="small">○ Business-approved regulatory semantics</p></div></div><div class="panel"><h2>BigQuery design reference</h2><p class="small">The project includes illustrative BigQuery DDL with partitioning and clustering. This code is not deployed to GCP. Python and SQLite execute the actual demonstration pipeline.</p><span class="badge warn">No BCBS 239 compliance claim</span></div></section><p class="note">VAULT360 · Fictional records only · Local, read-only report · Built to demonstrate data modeling, SQL, Python, lineage and data quality concepts.</p></main><script>const DATA=__PAYLOAD__;const q=DATA.quality;document.querySelector('#transactions').textContent=q.hubs.toLocaleString();document.querySelector('#versions').textContent=q.satellite_versions.toLocaleString();document.querySelector('#quarantined').textContent=q.quarantined;document.querySelector('#batches').textContent=q.batches;document.querySelector('#qualityPct').textContent=(100*q.hubs/(q.hubs+q.quarantined)).toFixed(2)+'%';document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')}));const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.getElementById('lineage').innerHTML=DATA.lineage.map(x=>`<p class="small"><b style="color:#65ebc5">${safe(x.asset)}</b><br>← ${safe(x.upstream)}<br>${safe(x.transformation)} · ${safe(x.owner)}</p>`).join('');document.getElementById('mart').innerHTML=DATA.monthly.map(x=>`<tr><td>${safe(x.month)}</td><td>${x.transactions}</td><td>${x.net_amount.toLocaleString('en-US',{minimumFractionDigits:2})}</td></tr>`).join('');const max=Math.max(...DATA.monthly.map(x=>x.transactions));document.getElementById('chart').innerHTML=DATA.monthly.map(x=>`<div class="barwrap"><div class="bar" title="${x.transactions} transactions" style="height:${Math.round(x.transactions/max*195)}px"></div><div class="barlabel">${safe(x.month)}</div></div>`).join('');function exportCsv(){const lines=['month,transactions,net_amount',...DATA.monthly.map(x=>`${x.month},${x.transactions},${x.net_amount}`)];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));a.download='vault360_monthly_mart.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}</script></body></html>'''
(ROOT/'index.html').write_text(page.replace('__PAYLOAD__',payload),encoding='utf-8')
print('Generated index.html')
